-- LOCAL MOCK ONLY. The not-ready barrier remains installed. These historical
-- labels grant no claim, reservation, provider access or successor authority.
-- The signed oracle and continuous external fence are assumptions of #296.
DROP TRIGGER IF EXISTS serial_classification_unimplemented;
CREATE TRIGGER serial_classification_integrity_guard BEFORE INSERT ON serial_pilot_classification_evidence WHEN
 EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_classification_not_ready','serial_classification_unimplemented','serial_pilot_fence_not_ready','serial_pilot_hold_not_ready','serial_job_provenance_not_ready','serial_source_provenance_not_ready','serial_pilot_oracle_fence_not_ready','serial_pilot_attested_handoff_not_ready','serial_pilot_oracle_revoke_not_ready'))
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_classification_parked_guard','serial_classification_not_started_guard','serial_classification_integrity_guard','serial_classification_no_replace','serial_classification_no_update','serial_classification_no_delete','serial_classification_close_parked','serial_classification_close_not_started','serial_classification_close_integrity'))<>9
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_pilot_fence_result','serial_pilot_fence_audit_no_replace','serial_pilot_fence_audit_no_update','serial_pilot_fence_audit_no_delete','serial_pilot_hold_no_replace','serial_pilot_hold_no_update','serial_pilot_hold_no_delete','serial_pilot_attested_handoff_no_replace','serial_pilot_attested_handoff_no_update','serial_pilot_attested_handoff_no_delete','serial_pilot_oracle_fence_no_replace','serial_pilot_oracle_fence_no_update','serial_pilot_oracle_fence_no_delete','serial_pilot_oracle_revoke_insert','serial_pilot_oracle_revoke_no_update','serial_pilot_oracle_revoke_no_delete'))<>16
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_source_provenance_no_update','serial_source_provenance_no_delete','serial_source_provenance_no_replace','serial_source_provenance_namespace_guard','serial_source_provenance_insert_guard','serial_source_provenance_update_guard','serial_source_provenance_delete_guard','serial_source_job_birth_guard','serial_job_provenance_insert_guard','serial_job_provenance_update_guard','serial_job_provenance_delete_guard','serial_job_provenance_activation_no_update','serial_job_provenance_activation_no_delete','serial_job_provenance_activation_no_replace','serial_job_provenance_source_gate','continuous_daily_post_no_delete','continuous_daily_post_no_update','continuous_daily_post_no_replace','continuous_daily_record_post_cutover'))<>19
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('continuous_review_close_insert','continuous_review_close_transition','continuous_review_close_no_delete','continuous_review_close_no_replace','continuous_notice_status_attempt_insert','continuous_notice_status_attempt_no_update','continuous_notice_status_attempt_no_delete','continuous_notice_status_attempt_no_replace'))<>8
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('stable_source_revision_expense_events_insert','stable_source_revision_expense_events_update','stable_source_revision_expense_events_delete','stable_source_revision_expense_documents_insert','stable_source_revision_expense_documents_update','stable_source_revision_expense_documents_delete','stable_source_revision_expense_document_links_insert','stable_source_revision_expense_document_links_update','stable_source_revision_expense_document_links_delete','stable_source_revision_expense_document_items_insert','stable_source_revision_expense_document_items_update','stable_source_revision_expense_document_items_delete','stable_source_revision_owner_personal_transactions_insert','stable_source_revision_owner_personal_transactions_update','stable_source_revision_owner_personal_transactions_delete','stable_source_revision_no_delete','stable_source_revision_no_replace','stable_source_revision_monotonic'))<>18
 BEGIN SELECT RAISE(ABORT,'classification integrity unverified'); END;

CREATE TRIGGER serial_classification_parked_guard BEFORE INSERT ON serial_pilot_classification_evidence WHEN NEW.category IS 'PARKED' AND NOT EXISTS(
 SELECT 1 FROM serial_pilot_rounds round JOIN serial_pilot_round_bindings binding ON binding.round_id=round.round_id
 JOIN serial_pilot_round_items b ON b.round_id=round.round_id AND b.job_id=NEW.job_id
 JOIN serial_pilot_round_items c ON c.round_id=b.round_id AND c.ordinal=b.ordinal+1 AND c.job_id=NEW.successor_job_id
 JOIN serial_pilot_hold_evidence hold ON hold.round_id=b.round_id AND hold.job_id=b.job_id AND hold.spreadsheet_id=binding.spreadsheet_id AND hold.fingerprint=binding.fingerprint
 JOIN sync_jobs job ON job.job_id=b.job_id AND job.entity_type='EXPENSE' AND job.entity_version=1 AND job.status='REVIEW' AND job.attempt_count=0 AND job.last_error='SERIAL_PILOT_B_REVIEW' AND job.lease_token IS NULL AND job.lease_until IS NULL AND job.serial_provenance_version=1 AND job.serial_lease_generation=0
 JOIN expense_events source ON source.expense_id=job.entity_key AND source.version=job.entity_version AND source.status='CONFIRMED' AND source.serial_source_namespace=hold.source_namespace
 JOIN serial_source_provenance_activation source_activation ON source_activation.singleton=1 AND source_activation.spreadsheet_id=binding.spreadsheet_id AND source_activation.namespace=source.serial_source_namespace
 JOIN serial_job_provenance_activation job_activation ON job_activation.singleton=1 AND job_activation.spreadsheet_id=binding.spreadsheet_id
 JOIN admin_audit root ON root.id=hold.audit_id AND root.action='ISSUE296_PAUSED_NOTICE_HANDOVER' AND root.entity_key=job.job_id AND root.reason=binding.fingerprint AND json_extract(root.before_json,'$.book')=binding.spreadsheet_id AND json_extract(root.after_json,'$.roundId')=round.round_id AND json_extract(root.after_json,'$.epoch')=hold.epoch_id
 JOIN stable_recovery_epochs previous ON previous.epoch_id=hold.epoch_id AND previous.spreadsheet_id=binding.spreadsheet_id AND previous.target_type='EXPENSE' AND previous.target_key=job.entity_key AND previous.target_version=job.entity_version AND previous.state='CLOSED'
 JOIN serial_pilot_attested_handoffs handoff ON handoff.round_id=round.round_id AND handoff.predecessor_job_id=b.job_id AND handoff.successor_job_id=c.job_id AND handoff.predecessor_epoch_id=previous.epoch_id AND handoff.spreadsheet_id=binding.spreadsheet_id AND handoff.claim_token=json_extract(root.after_json,'$.token') AND handoff.worker_version=json_extract(root.after_json,'$.version') AND handoff.nonce=NEW.attestation_nonce
 JOIN sync_jobs successor_job ON successor_job.job_id=c.job_id AND successor_job.entity_type='EXPENSE'
 JOIN stable_recovery_epochs successor_epoch ON successor_epoch.epoch_id=handoff.successor_epoch_id AND successor_epoch.spreadsheet_id=binding.spreadsheet_id AND successor_epoch.target_type=successor_job.entity_type AND successor_epoch.target_key=successor_job.entity_key AND successor_epoch.target_version=successor_job.entity_version
 JOIN admin_audit edge ON edge.id='issue296:serial:'||b.job_id AND edge.action='ISSUE296_SERIAL_EXPENSE_HANDOVER' AND edge.entity_key=c.job_id AND edge.reason=binding.fingerprint AND json_extract(edge.before_json,'$.book')=binding.spreadsheet_id AND json_extract(edge.before_json,'$.predecessorJobId')=b.job_id AND json_extract(edge.before_json,'$.proof')=handoff.payload_digest AND json_extract(edge.after_json,'$.roundId')=round.round_id AND json_extract(edge.after_json,'$.epoch')=handoff.successor_epoch_id AND json_extract(edge.after_json,'$.token')=handoff.claim_token AND json_extract(edge.after_json,'$.attestationNonce')=handoff.nonce AND json_extract(edge.after_json,'$.version')=handoff.worker_version
 JOIN stable_source_revision revision ON revision.singleton=1 AND revision.revision=handoff.source_revision
 JOIN serial_pilot_oracle_fence fence ON fence.spreadsheet_id=handoff.spreadsheet_id AND fence.fence_digest=handoff.fence_digest AND fence.generation=handoff.fence_generation
 WHERE (((round.round_id=NEW.round_id AND (round.state='OPEN' AND NEW.evidence='MOCK_ATTESTED_HANDOFF')) AND ((NEW.source_namespace=source.serial_source_namespace AND NEW.source_revision=revision.revision) AND (NEW.fence_digest=fence.fence_digest AND NEW.fence_generation=fence.generation))) AND (((NEW.worker_version=handoff.worker_version AND length(handoff.payload_digest)=64) AND (handoff.payload_digest NOT GLOB '*[^0-9a-f]*' AND length(handoff.signature_digest)=64)) AND ((handoff.signature_digest NOT GLOB '*[^0-9a-f]*' AND (SELECT count(*) FROM serial_pilot_attested_handoffs h WHERE h.round_id=round.round_id AND h.predecessor_job_id=b.job_id)=1) AND ((SELECT count(*) FROM admin_audit x WHERE x.action='ISSUE296_SERIAL_EXPENSE_HANDOVER' AND json_extract(x.after_json,'$.roundId')=round.round_id AND json_extract(x.before_json,'$.predecessorJobId')=b.job_id)=1 AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations revoked WHERE revoked.spreadsheet_id=fence.spreadsheet_id AND revoked.fence_digest=fence.fence_digest AND revoked.fence_generation=fence.generation)))))
) BEGIN SELECT RAISE(ABORT,'parked classification unverified'); END;

CREATE TRIGGER serial_classification_not_started_guard BEFORE INSERT ON serial_pilot_classification_evidence WHEN NEW.category IS 'NOT_STARTED' AND NOT EXISTS(
 SELECT 1 FROM serial_pilot_rounds round JOIN serial_pilot_round_bindings binding ON binding.round_id=round.round_id
 JOIN serial_pilot_round_items item ON item.round_id=round.round_id AND item.job_id=NEW.job_id
 JOIN sync_jobs job ON job.job_id=item.job_id AND job.entity_type='EXPENSE' AND job.entity_version=1 AND job.status='PENDING' AND job.attempt_count=0 AND job.lease_token IS NULL AND job.lease_until IS NULL AND job.serial_provenance_version=1 AND job.serial_lease_generation=0
 JOIN expense_events source ON source.expense_id=job.entity_key AND source.version=job.entity_version AND source.status='CONFIRMED' AND source.serial_source_namespace=NEW.source_namespace
 JOIN serial_source_provenance_activation source_activation ON source_activation.singleton=1 AND source_activation.spreadsheet_id=binding.spreadsheet_id AND source_activation.namespace=source.serial_source_namespace
 JOIN serial_job_provenance_activation job_activation ON job_activation.singleton=1 AND job_activation.spreadsheet_id=binding.spreadsheet_id
 JOIN continuous_daily_post_cutover_expenses cohort ON cohort.spreadsheet_id=binding.spreadsheet_id AND cohort.expense_id=job.entity_key
 JOIN stable_source_revision revision ON revision.singleton=1 AND revision.revision=NEW.source_revision
 JOIN serial_pilot_classification_evidence parked ON parked.round_id=round.round_id AND parked.category='PARKED' AND parked.attestation_nonce=NEW.attestation_nonce AND parked.source_revision=revision.revision AND parked.fence_digest=NEW.fence_digest AND parked.fence_generation=NEW.fence_generation
 JOIN serial_pilot_attested_handoffs handoff ON handoff.nonce=parked.attestation_nonce AND handoff.round_id=round.round_id AND handoff.spreadsheet_id=binding.spreadsheet_id AND handoff.source_revision=revision.revision
 JOIN serial_pilot_oracle_fence fence ON fence.spreadsheet_id=handoff.spreadsheet_id AND fence.fence_digest=handoff.fence_digest AND fence.generation=handoff.fence_generation
 WHERE ((((round.round_id=NEW.round_id AND round.state='OPEN') AND (NEW.evidence='MOCK_NEVER_STARTED' AND (NEW.successor_job_id IS NULL AND NEW.fence_digest=fence.fence_digest))) AND ((NEW.fence_generation=fence.generation AND (NEW.worker_version=handoff.worker_version AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations revoked WHERE revoked.spreadsheet_id=fence.spreadsheet_id AND revoked.fence_digest=fence.fence_digest AND revoked.fence_generation=fence.generation))) AND (NOT EXISTS(SELECT 1 FROM stable_workbook_claims claim WHERE claim.spreadsheet_id=binding.spreadsheet_id) AND (NOT EXISTS(SELECT 1 FROM stable_recovery_epochs epoch WHERE epoch.target_type='EXPENSE' AND epoch.target_key=job.entity_key) AND NOT EXISTS(SELECT 1 FROM sync_jobs other WHERE other.entity_type='EXPENSE' AND other.entity_key=job.entity_key AND other.job_id<>job.job_id))))) AND (((NOT EXISTS(SELECT 1 FROM failed_jobs failed WHERE failed.queue_name='malipang-jobs' AND substr(failed.job_key,1,length('EXPENSE:'||job.entity_key)+1)='EXPENSE:'||job.entity_key||':') AND (NOT EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.entity_key IN (job.job_id,job.entity_key)) AND NOT EXISTS(SELECT 1 FROM serial_pilot_hold_evidence hold WHERE hold.job_id=job.job_id))) AND (NOT EXISTS(SELECT 1 FROM stable_projection_writes p WHERE p.entity_type='EXPENSE' AND (p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|')) AND (NOT EXISTS(SELECT 1 FROM stable_expense_cancellation_writes p WHERE p.entity_type='EXPENSE' AND (p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|')) AND NOT EXISTS(SELECT 1 FROM stable_expense_projection_preimages p WHERE p.entity_type='EXPENSE' AND (p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|'))))) AND ((NOT EXISTS(SELECT 1 FROM atomic_daily_marker_reservations p WHERE p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|') AND (NOT EXISTS(SELECT 1 FROM continuous_daily_write_evidence p WHERE p.entity_id=job.entity_key) AND NOT EXISTS(SELECT 1 FROM continuous_ledger_write_evidence p WHERE p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|'))) AND (NOT EXISTS(SELECT 1 FROM continuous_publication_intents p WHERE p.entity_id=job.entity_key) AND (NOT EXISTS(SELECT 1 FROM continuous_publication_markers p WHERE p.entity_id=job.entity_key) AND NOT EXISTS(SELECT 1 FROM continuous_review_notice_close close_notice WHERE close_notice.expense_id=job.entity_key)
  AND NOT EXISTS(SELECT 1 FROM continuous_notice_status_attempts notice LEFT JOIN continuous_review_notice_close close_notice ON close_notice.operation_token=notice.operation_token WHERE (notice.spreadsheet_id=binding.spreadsheet_id OR close_notice.spreadsheet_id=binding.spreadsheet_id) AND (close_notice.operation_token IS NULL OR close_notice.spreadsheet_id IS NOT notice.spreadsheet_id OR close_notice.expense_id=job.entity_key)))))))
) BEGIN SELECT RAISE(ABORT,'not-started classification unverified'); END;

-- Evidence may have been committed separately; revalidate every positive
-- result and every PARKED anchor of a NOT_STARTED result at round closure.
CREATE TRIGGER serial_classification_close_parked BEFORE UPDATE OF state ON serial_pilot_rounds WHEN OLD.state='OPEN' AND NEW.state='CLOSED' AND EXISTS(SELECT 1 FROM serial_pilot_round_fence_activation WHERE singleton=1) AND EXISTS(
 SELECT 1 FROM serial_pilot_classification_evidence e WHERE e.round_id=OLD.round_id AND e.category='PARKED' AND (
  EXISTS(SELECT 1 FROM serial_pilot_round_results r WHERE r.round_id=e.round_id AND r.job_id=e.job_id AND r.category=e.category AND r.evidence=e.evidence AND r.successor_job_id IS e.successor_job_id) OR
  EXISTS(SELECT 1 FROM serial_pilot_round_results r JOIN serial_pilot_classification_evidence n ON n.round_id=r.round_id AND n.job_id=r.job_id AND n.category=r.category AND n.evidence=r.evidence WHERE r.round_id=e.round_id AND r.category='NOT_STARTED' AND n.attestation_nonce=e.attestation_nonce))
 AND NOT EXISTS(
 SELECT 1 FROM serial_pilot_rounds round JOIN serial_pilot_round_bindings binding ON binding.round_id=round.round_id
 JOIN serial_pilot_round_items b ON b.round_id=round.round_id AND b.job_id=e.job_id
 JOIN serial_pilot_round_items c ON c.round_id=b.round_id AND c.ordinal=b.ordinal+1 AND c.job_id=e.successor_job_id
 JOIN serial_pilot_hold_evidence hold ON hold.round_id=b.round_id AND hold.job_id=b.job_id AND hold.spreadsheet_id=binding.spreadsheet_id AND hold.fingerprint=binding.fingerprint
 JOIN sync_jobs job ON job.job_id=b.job_id AND job.entity_type='EXPENSE' AND job.entity_version=1 AND job.status='REVIEW' AND job.attempt_count=0 AND job.last_error='SERIAL_PILOT_B_REVIEW' AND job.lease_token IS NULL AND job.lease_until IS NULL AND job.serial_provenance_version=1 AND job.serial_lease_generation=0
 JOIN expense_events source ON source.expense_id=job.entity_key AND source.version=job.entity_version AND source.status='CONFIRMED' AND source.serial_source_namespace=hold.source_namespace
 JOIN serial_source_provenance_activation source_activation ON source_activation.singleton=1 AND source_activation.spreadsheet_id=binding.spreadsheet_id AND source_activation.namespace=source.serial_source_namespace
 JOIN serial_job_provenance_activation job_activation ON job_activation.singleton=1 AND job_activation.spreadsheet_id=binding.spreadsheet_id
 JOIN admin_audit root ON root.id=hold.audit_id AND root.action='ISSUE296_PAUSED_NOTICE_HANDOVER' AND root.entity_key=job.job_id AND root.reason=binding.fingerprint AND json_extract(root.before_json,'$.book')=binding.spreadsheet_id AND json_extract(root.after_json,'$.roundId')=round.round_id AND json_extract(root.after_json,'$.epoch')=hold.epoch_id
 JOIN stable_recovery_epochs previous ON previous.epoch_id=hold.epoch_id AND previous.spreadsheet_id=binding.spreadsheet_id AND previous.target_type='EXPENSE' AND previous.target_key=job.entity_key AND previous.target_version=job.entity_version AND previous.state='CLOSED'
 JOIN serial_pilot_attested_handoffs handoff ON handoff.round_id=round.round_id AND handoff.predecessor_job_id=b.job_id AND handoff.successor_job_id=c.job_id AND handoff.predecessor_epoch_id=previous.epoch_id AND handoff.spreadsheet_id=binding.spreadsheet_id AND handoff.claim_token=json_extract(root.after_json,'$.token') AND handoff.worker_version=json_extract(root.after_json,'$.version') AND handoff.nonce=e.attestation_nonce
 JOIN sync_jobs successor_job ON successor_job.job_id=c.job_id AND successor_job.entity_type='EXPENSE'
 JOIN stable_recovery_epochs successor_epoch ON successor_epoch.epoch_id=handoff.successor_epoch_id AND successor_epoch.spreadsheet_id=binding.spreadsheet_id AND successor_epoch.target_type=successor_job.entity_type AND successor_epoch.target_key=successor_job.entity_key AND successor_epoch.target_version=successor_job.entity_version
 JOIN admin_audit edge ON edge.id='issue296:serial:'||b.job_id AND edge.action='ISSUE296_SERIAL_EXPENSE_HANDOVER' AND edge.entity_key=c.job_id AND edge.reason=binding.fingerprint AND json_extract(edge.before_json,'$.book')=binding.spreadsheet_id AND json_extract(edge.before_json,'$.predecessorJobId')=b.job_id AND json_extract(edge.before_json,'$.proof')=handoff.payload_digest AND json_extract(edge.after_json,'$.roundId')=round.round_id AND json_extract(edge.after_json,'$.epoch')=handoff.successor_epoch_id AND json_extract(edge.after_json,'$.token')=handoff.claim_token AND json_extract(edge.after_json,'$.attestationNonce')=handoff.nonce AND json_extract(edge.after_json,'$.version')=handoff.worker_version
 JOIN stable_source_revision revision ON revision.singleton=1 AND revision.revision=handoff.source_revision
 JOIN serial_pilot_oracle_fence fence ON fence.spreadsheet_id=handoff.spreadsheet_id AND fence.fence_digest=handoff.fence_digest AND fence.generation=handoff.fence_generation
 WHERE (((round.round_id=e.round_id AND (round.state='OPEN' AND e.evidence='MOCK_ATTESTED_HANDOFF')) AND ((e.source_namespace=source.serial_source_namespace AND e.source_revision=revision.revision) AND (e.fence_digest=fence.fence_digest AND e.fence_generation=fence.generation))) AND (((e.worker_version=handoff.worker_version AND length(handoff.payload_digest)=64) AND (handoff.payload_digest NOT GLOB '*[^0-9a-f]*' AND length(handoff.signature_digest)=64)) AND ((handoff.signature_digest NOT GLOB '*[^0-9a-f]*' AND (SELECT count(*) FROM serial_pilot_attested_handoffs h WHERE h.round_id=round.round_id AND h.predecessor_job_id=b.job_id)=1) AND ((SELECT count(*) FROM admin_audit x WHERE x.action='ISSUE296_SERIAL_EXPENSE_HANDOVER' AND json_extract(x.after_json,'$.roundId')=round.round_id AND json_extract(x.before_json,'$.predecessorJobId')=b.job_id)=1 AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations revoked WHERE revoked.spreadsheet_id=fence.spreadsheet_id AND revoked.fence_digest=fence.fence_digest AND revoked.fence_generation=fence.generation)))))
)) BEGIN SELECT RAISE(ABORT,'parked classification changed before close'); END;

CREATE TRIGGER serial_classification_close_not_started BEFORE UPDATE OF state ON serial_pilot_rounds WHEN OLD.state='OPEN' AND NEW.state='CLOSED' AND EXISTS(SELECT 1 FROM serial_pilot_round_fence_activation WHERE singleton=1) AND EXISTS(
 SELECT 1 FROM serial_pilot_classification_evidence e JOIN serial_pilot_round_results r ON r.round_id=e.round_id AND r.job_id=e.job_id AND r.category=e.category AND r.evidence=e.evidence AND r.successor_job_id IS e.successor_job_id WHERE e.round_id=OLD.round_id AND e.category='NOT_STARTED' AND NOT EXISTS(
 SELECT 1 FROM serial_pilot_rounds round JOIN serial_pilot_round_bindings binding ON binding.round_id=round.round_id
 JOIN serial_pilot_round_items item ON item.round_id=round.round_id AND item.job_id=e.job_id
 JOIN sync_jobs job ON job.job_id=item.job_id AND job.entity_type='EXPENSE' AND job.entity_version=1 AND job.status='PENDING' AND job.attempt_count=0 AND job.lease_token IS NULL AND job.lease_until IS NULL AND job.serial_provenance_version=1 AND job.serial_lease_generation=0
 JOIN expense_events source ON source.expense_id=job.entity_key AND source.version=job.entity_version AND source.status='CONFIRMED' AND source.serial_source_namespace=e.source_namespace
 JOIN serial_source_provenance_activation source_activation ON source_activation.singleton=1 AND source_activation.spreadsheet_id=binding.spreadsheet_id AND source_activation.namespace=source.serial_source_namespace
 JOIN serial_job_provenance_activation job_activation ON job_activation.singleton=1 AND job_activation.spreadsheet_id=binding.spreadsheet_id
 JOIN continuous_daily_post_cutover_expenses cohort ON cohort.spreadsheet_id=binding.spreadsheet_id AND cohort.expense_id=job.entity_key
 JOIN stable_source_revision revision ON revision.singleton=1 AND revision.revision=e.source_revision
 JOIN serial_pilot_classification_evidence parked ON parked.round_id=round.round_id AND parked.category='PARKED' AND parked.attestation_nonce=e.attestation_nonce AND parked.source_revision=revision.revision AND parked.fence_digest=e.fence_digest AND parked.fence_generation=e.fence_generation
 JOIN serial_pilot_attested_handoffs handoff ON handoff.nonce=parked.attestation_nonce AND handoff.round_id=round.round_id AND handoff.spreadsheet_id=binding.spreadsheet_id AND handoff.source_revision=revision.revision
 JOIN serial_pilot_oracle_fence fence ON fence.spreadsheet_id=handoff.spreadsheet_id AND fence.fence_digest=handoff.fence_digest AND fence.generation=handoff.fence_generation
 WHERE ((((round.round_id=e.round_id AND round.state='OPEN') AND (e.evidence='MOCK_NEVER_STARTED' AND (e.successor_job_id IS NULL AND e.fence_digest=fence.fence_digest))) AND ((e.fence_generation=fence.generation AND (e.worker_version=handoff.worker_version AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations revoked WHERE revoked.spreadsheet_id=fence.spreadsheet_id AND revoked.fence_digest=fence.fence_digest AND revoked.fence_generation=fence.generation))) AND (NOT EXISTS(SELECT 1 FROM stable_workbook_claims claim WHERE claim.spreadsheet_id=binding.spreadsheet_id) AND (NOT EXISTS(SELECT 1 FROM stable_recovery_epochs epoch WHERE epoch.target_type='EXPENSE' AND epoch.target_key=job.entity_key) AND NOT EXISTS(SELECT 1 FROM sync_jobs other WHERE other.entity_type='EXPENSE' AND other.entity_key=job.entity_key AND other.job_id<>job.job_id))))) AND (((NOT EXISTS(SELECT 1 FROM failed_jobs failed WHERE failed.queue_name='malipang-jobs' AND substr(failed.job_key,1,length('EXPENSE:'||job.entity_key)+1)='EXPENSE:'||job.entity_key||':') AND (NOT EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.entity_key IN (job.job_id,job.entity_key)) AND NOT EXISTS(SELECT 1 FROM serial_pilot_hold_evidence hold WHERE hold.job_id=job.job_id))) AND (NOT EXISTS(SELECT 1 FROM stable_projection_writes p WHERE p.entity_type='EXPENSE' AND (p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|')) AND (NOT EXISTS(SELECT 1 FROM stable_expense_cancellation_writes p WHERE p.entity_type='EXPENSE' AND (p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|')) AND NOT EXISTS(SELECT 1 FROM stable_expense_projection_preimages p WHERE p.entity_type='EXPENSE' AND (p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|'))))) AND ((NOT EXISTS(SELECT 1 FROM atomic_daily_marker_reservations p WHERE p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|') AND (NOT EXISTS(SELECT 1 FROM continuous_daily_write_evidence p WHERE p.entity_id=job.entity_key) AND NOT EXISTS(SELECT 1 FROM continuous_ledger_write_evidence p WHERE p.entity_id=job.entity_key OR substr(p.entity_id,1,length(job.entity_key)+1)=job.entity_key||'|'))) AND (NOT EXISTS(SELECT 1 FROM continuous_publication_intents p WHERE p.entity_id=job.entity_key) AND (NOT EXISTS(SELECT 1 FROM continuous_publication_markers p WHERE p.entity_id=job.entity_key) AND NOT EXISTS(SELECT 1 FROM continuous_review_notice_close close_notice WHERE close_notice.expense_id=job.entity_key)
  AND NOT EXISTS(SELECT 1 FROM continuous_notice_status_attempts notice LEFT JOIN continuous_review_notice_close close_notice ON close_notice.operation_token=notice.operation_token WHERE (notice.spreadsheet_id=binding.spreadsheet_id OR close_notice.spreadsheet_id=binding.spreadsheet_id) AND (close_notice.operation_token IS NULL OR close_notice.spreadsheet_id IS NOT notice.spreadsheet_id OR close_notice.expense_id=job.entity_key)))))))
)) BEGIN SELECT RAISE(ABORT,'not-started classification changed before close'); END;

CREATE TRIGGER serial_classification_close_integrity BEFORE UPDATE OF state ON serial_pilot_rounds WHEN OLD.state='OPEN' AND NEW.state='CLOSED' AND EXISTS(SELECT 1 FROM serial_pilot_round_fence_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM serial_pilot_round_results r WHERE r.round_id=OLD.round_id AND r.category IN ('PARKED','NOT_STARTED')) AND ( EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_classification_not_ready','serial_classification_unimplemented','serial_pilot_fence_not_ready','serial_pilot_hold_not_ready','serial_job_provenance_not_ready','serial_source_provenance_not_ready','serial_pilot_oracle_fence_not_ready','serial_pilot_attested_handoff_not_ready','serial_pilot_oracle_revoke_not_ready'))
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_classification_parked_guard','serial_classification_not_started_guard','serial_classification_integrity_guard','serial_classification_no_replace','serial_classification_no_update','serial_classification_no_delete','serial_classification_close_parked','serial_classification_close_not_started','serial_classification_close_integrity'))<>9
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_pilot_fence_result','serial_pilot_fence_audit_no_replace','serial_pilot_fence_audit_no_update','serial_pilot_fence_audit_no_delete','serial_pilot_hold_no_replace','serial_pilot_hold_no_update','serial_pilot_hold_no_delete','serial_pilot_attested_handoff_no_replace','serial_pilot_attested_handoff_no_update','serial_pilot_attested_handoff_no_delete','serial_pilot_oracle_fence_no_replace','serial_pilot_oracle_fence_no_update','serial_pilot_oracle_fence_no_delete','serial_pilot_oracle_revoke_insert','serial_pilot_oracle_revoke_no_update','serial_pilot_oracle_revoke_no_delete'))<>16
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_source_provenance_no_update','serial_source_provenance_no_delete','serial_source_provenance_no_replace','serial_source_provenance_namespace_guard','serial_source_provenance_insert_guard','serial_source_provenance_update_guard','serial_source_provenance_delete_guard','serial_source_job_birth_guard','serial_job_provenance_insert_guard','serial_job_provenance_update_guard','serial_job_provenance_delete_guard','serial_job_provenance_activation_no_update','serial_job_provenance_activation_no_delete','serial_job_provenance_activation_no_replace','serial_job_provenance_source_gate','continuous_daily_post_no_delete','continuous_daily_post_no_update','continuous_daily_post_no_replace','continuous_daily_record_post_cutover'))<>19
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('continuous_review_close_insert','continuous_review_close_transition','continuous_review_close_no_delete','continuous_review_close_no_replace','continuous_notice_status_attempt_insert','continuous_notice_status_attempt_no_update','continuous_notice_status_attempt_no_delete','continuous_notice_status_attempt_no_replace'))<>8
 OR (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('stable_source_revision_expense_events_insert','stable_source_revision_expense_events_update','stable_source_revision_expense_events_delete','stable_source_revision_expense_documents_insert','stable_source_revision_expense_documents_update','stable_source_revision_expense_documents_delete','stable_source_revision_expense_document_links_insert','stable_source_revision_expense_document_links_update','stable_source_revision_expense_document_links_delete','stable_source_revision_expense_document_items_insert','stable_source_revision_expense_document_items_update','stable_source_revision_expense_document_items_delete','stable_source_revision_owner_personal_transactions_insert','stable_source_revision_owner_personal_transactions_update','stable_source_revision_owner_personal_transactions_delete','stable_source_revision_no_delete','stable_source_revision_no_replace','stable_source_revision_monotonic'))<>18) BEGIN SELECT RAISE(ABORT,'classification integrity changed before close'); END;
